// Route every spawned CLI away from the developer's real ~/.config/entire
// (contexts.json, version_check.json), ~/.cache/entire (discovery caches and
// auth-go locks), and OS keychain. testing.Testing() is false in the
// subprocess, so the internal/testdirs fallback cannot protect it —
// isolation must come from the environment, which children inherit because
// all integration env building starts from os.Environ() (testutil.GitIsolatedEnv).

//go:build integration

package integration

import (
	"bufio"
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

// fakeLoginJWT builds a JWT-shaped access token with a junk signature
// (ParseClaims doesn't verify signatures) whose iss matches the test server
// origin, so login's iss cross-check passes and the context can be recorded.
// A bare opaque token is no longer enough for a --server login: with no iss
// claim there is nothing to key the login context by, and login fails.
func fakeLoginJWT(iss string) string {
	enc := base64.RawURLEncoding
	header := enc.EncodeToString([]byte(`{"alg":"RS256","typ":"JWT"}`))
	payload := enc.EncodeToString(fmt.Appendf(nil,
		`{"iss":%q,"sub":"user-123","exp":%d}`, iss, time.Now().Add(time.Hour).Unix()))
	return header + "." + payload + "." + enc.EncodeToString([]byte("sig"))
}

